public class CappedTaskQueueTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("capacity below 1 clamps to 1", 1, new CappedTaskQueue(0).capacity());

            CappedTaskQueue chores = new CappedTaskQueue(2);
            chores.offer("wash");
            chores.offer("dry");
            check("offer when full is refused", false, chores.offer("fold"));
            check("size stays at the capacity", 2, chores.size());
            check("isFull once capacity is reached", true, chores.isFull());

            CappedTaskQueue fresh = new CappedTaskQueue(5);
            check("blank task refused", false, fresh.offer("   "));
            check("poll on an empty queue", null, fresh.poll());

            check("poll returns the oldest task", "wash", chores.poll());
            check("peek shows the next task", "dry", chores.peek());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

