import java.util.ArrayList;
import java.util.List;

public class CappedTaskQueue {

    private final List<String> tasks = new ArrayList<>();
    private final int capacity;

    public CappedTaskQueue(int capacity) {
        this.capacity = capacity < 1 ? 1 : capacity;
    }

    public int capacity() {
        return capacity;
    }

    public int size() {
        return tasks.size();
    }

    public boolean isFull() {
        return tasks.size() >= capacity;
    }

    /** Adds task at the back; returns false (changing nothing) if it cannot be stored. */
    public boolean offer(String task) {
        if (task == null || task.trim().isEmpty()) {
            return false;
        }
        if (isFull()) {
            return false;
        }
        tasks.add(task);
        return true;
    }

    /** Removes and returns the oldest task, or null when the queue is empty. */
    public String poll() {
        if (tasks.isEmpty()) {
            return null;
        }
        return tasks.remove(0);
    }

    /** Returns the oldest task without removing it, or null when the queue is empty. */
    public String peek() {
        if (tasks.isEmpty()) {
            return null;
        }
        return tasks.get(0);
    }
}
